package migrate

import (
	"database/sql"
	"fmt"
	"slices"
)

// Run adds the orders.status column and backfills it.
//
// Run is idempotent: it can be rerun after a crash at any point and converges
// to the same end state. The column is added only if missing, and the backfill
// only touches orders that have not been backfilled yet, atomically.
func Run(db *sql.DB) error {
	if err := addStatusColumn(db); err != nil {
		return fmt.Errorf("add column: %w", err)
	}
	if err := backfill(db); err != nil {
		return fmt.Errorf("backfill: %w", err)
	}
	return nil
}

func addStatusColumn(db *sql.DB) error {
	rows, err := db.Query(`SELECT * FROM orders LIMIT 0`)
	if err != nil {
		return err
	}
	cols, err := rows.Columns()
	rows.Close()
	if err != nil {
		return err
	}
	if slices.Contains(cols, "status") {
		return nil
	}
	_, err = db.Exec(`ALTER TABLE orders ADD COLUMN status TEXT`)
	return err
}

func backfill(db *sql.DB) error {
	tx, err := db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	if _, err := tx.Exec(`
		INSERT INTO order_events (order_id, kind)
		SELECT o.id, 'backfilled' FROM orders o
		WHERE NOT EXISTS (
			SELECT 1 FROM order_events e
			WHERE e.order_id = o.id AND e.kind = 'backfilled'
		)`); err != nil {
		return fmt.Errorf("insert events: %w", err)
	}
	if _, err := tx.Exec(`UPDATE orders SET status = 'open' WHERE status IS NULL`); err != nil {
		return fmt.Errorf("set status: %w", err)
	}
	return tx.Commit()
}

