package check

import (
	"database/sql"
	"testing"

	"example.com/shop/migrate"
	_ "modernc.org/sqlite"
)

// Simulates the crash: column added, order 1 fully backfilled,
// order 2 got its event but not its status, order 3 untouched.
func TestRerunAfterPartialCrash(t *testing.T) {
	db, err := sql.Open("sqlite", ":memory:")
	if err != nil { t.Fatal(err) }
	db.SetMaxOpenConns(1)
	for _, q := range []string{
		`CREATE TABLE orders (id INTEGER PRIMARY KEY)`,
		`CREATE TABLE order_events (order_id INTEGER, kind TEXT)`,
		`INSERT INTO orders (id) VALUES (1),(2),(3)`,
		`ALTER TABLE orders ADD COLUMN status TEXT`,
		`INSERT INTO order_events VALUES (1,'backfilled'),(2,'backfilled')`,
		`UPDATE orders SET status='open' WHERE id=1`,
	} {
		if _, err := db.Exec(q); err != nil { t.Fatal(q, err) }
	}
	for i := 0; i < 2; i++ {
		if err := migrate.Run(db); err != nil { t.Fatalf("run %d: %v", i, err) }
	}
	var events, open int
	db.QueryRow(`SELECT COUNT(*) FROM order_events WHERE kind='backfilled'`).Scan(&events)
	db.QueryRow(`SELECT COUNT(*) FROM orders WHERE status='open'`).Scan(&open)
	if events != 3 || open != 3 { t.Fatalf("events=%d open=%d, want 3 and 3", events, open) }
}

func TestFreshDB(t *testing.T) {
	db, _ := sql.Open("sqlite", ":memory:")
	db.SetMaxOpenConns(1)
	db.Exec(`CREATE TABLE orders (id INTEGER PRIMARY KEY)`)
	db.Exec(`CREATE TABLE order_events (order_id INTEGER, kind TEXT)`)
	db.Exec(`INSERT INTO orders (id) VALUES (1),(2)`)
	if err := migrate.Run(db); err != nil { t.Fatal(err) }
	if err := migrate.Run(db); err != nil { t.Fatal(err) }
	var events, open int
	db.QueryRow(`SELECT COUNT(*) FROM order_events`).Scan(&events)
	db.QueryRow(`SELECT COUNT(*) FROM orders WHERE status='open'`).Scan(&open)
	if events != 2 || open != 2 { t.Fatalf("events=%d open=%d, want 2 and 2", events, open) }
}
EOF
cd $T && go get modernc.org/sqlite >/dev/null 2>&1 && go test ./check -v 2>&1 | tail -8; echo "dir: $T"

